import{_ as a,c as t,o,ag as s}from"./chunks/framework.DZ_cNctr.js";const g=JSON.parse('{"title":"OME-Zarr Viewer","description":"Free online OME-Zarr viewer: open OME-Zarr 0.3 to 0.6 images and plates in your browser, from a folder, one zipped file or a link. Nothing to install.","frontmatter":{"title":"OME-Zarr Viewer","description":"Free online OME-Zarr viewer: open OME-Zarr 0.3 to 0.6 images and plates in your browser, from a folder, one zipped file or a link. Nothing to install."},"headers":[],"relativePath":"guides/ome-zarr.md","filePath":"guides/ome-zarr.md"}'),r={name:"guides/ome-zarr.md"};function i(n,e,l,d,h,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="ome-zarr-viewer" tabindex="-1">OME-Zarr Viewer <a class="header-anchor" href="#ome-zarr-viewer" aria-label="Permalink to &quot;OME-Zarr Viewer&quot;">​</a></h1><p>OME-Zarr is the viewer&#39;s home format. It opens in place: nothing is converted and nothing is uploaded. New to the format? <a href="https://www.find-nuclei.com/blog/why-ome-zarr" target="_blank" rel="noreferrer">Why OME-Zarr Is Taking Over Microscopy</a> covers what it is good for.</p><ul><li><strong>OME-NGFF versions</strong> 0.3, 0.4, 0.5 and 0.6.</li><li><strong>Zarr v2</strong>, uncompressed or compressed with blosc, zlib or gzip.</li><li><strong>Zarr v3</strong>, sharded or not, compressed with blosc, zstd, gzip or zlib.</li><li><strong>Single images</strong>, and datasets with several series from bioformats2raw.</li><li><strong>HCS plates</strong>, with plate, well and field views. See <a href="./hcs-plates.html">OME-Zarr Plates</a>.</li><li><strong>Labels</strong> in the image&#39;s <code>labels/</code> group. They load with the image. On a plate, press <strong>Discover</strong>. See <a href="./labels.html">Labels</a>.</li></ul><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>A folder on your disk</strong>, in Chrome and Edge. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>One zipped file</strong> (<code>.ozx</code> or <code>.zip</code>), in any browser, from your disk or its address. See <a href="#a-dataset-in-a-single-file">A Dataset in a Single File</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><p>Local or remote? <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> helps you pick.</p><p>A Z-stack can also be viewed in 3D, whichever of these it was opened from. A folder still needs Chrome or Edge. See <a href="./3d-rendering.html#requirements-and-limits">3D Rendering</a>.</p><h2 id="a-dataset-in-a-single-file" tabindex="-1">A Dataset in a Single File <a class="header-anchor" href="#a-dataset-in-a-single-file" aria-label="Permalink to &quot;A Dataset in a Single File&quot;">​</a></h2><p>An OME-Zarr dataset is thousands of small files in nested folders. That shape is what makes it fast to read one region without reading the whole image. It is also what makes it awkward to send someone or carry on a stick.</p><p>The format has an answer: pack the whole dataset into one ZIP archive. Name it <code>.ozx</code>, or leave it as <code>.zip</code>. Both open here.</p><p><strong>To open one</strong>, drop it onto the viewer, or click <strong>Open Image</strong> and then <strong>Choose File</strong> on the <strong>Local Files</strong> tab. It opens the way a folder does, with the same plate navigation, the same channels and the same speed. The viewer reads pieces of the archive as it needs them, so a large dataset never has to be unpacked first.</p><p><strong>This route works in every browser</strong>, Safari and Firefox included. It is the only way to open an OME-Zarr dataset from your own disk in those two.</p><h3 id="making-one" tabindex="-1">Making one <a class="header-anchor" href="#making-one" aria-label="Permalink to &quot;Making one&quot;">​</a></h3><p>The quickest way is the one your computer already has. Right-click the dataset folder and choose <strong>Compress</strong> on macOS, or <strong>Send to › Compressed (zipped) folder</strong> on Windows. The zip holds the folder itself, and it opens here as it is.</p><p>For the smallest and fastest archive, zip the <strong>contents</strong> of the folder from the command line instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-dataset.ome.zarr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../your-dataset.ozx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.DS_Store&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*/.DS_Store&#39;</span></span></code></pre></div><p>That is the whole recipe. Three details in it matter.</p><p><code>.</code> rather than the folder name puts <code>zarr.json</code> at the top of the archive, which is the <code>.ozx</code> layout other tools expect. The viewer opens it either way.</p><p><code>-0</code> stores the files instead of compressing them. Zarr chunks are already compressed, so compressing them again costs time on both ends and saves almost nothing. Stored entries are also the fastest to read a piece of.</p><p>The <code>-x</code> at the end drops the hidden files macOS leaves in any folder you have opened in Finder. They are harmless, and without it a plate picks up one in every row. Leave it off on Linux and Windows.</p><p>Any tool works. Name the result <code>.ozx</code> or <code>.zip</code>, whichever you prefer.</p><div class="tip custom-block"><p class="custom-block-title">Check it opened the way you meant</p><p>Drop the archive on the viewer. If it opens, it is right. If you see a message that it holds no dataset the viewer can find, the dataset is neither at the top of the archive nor in a single folder there. Two datasets zipped side by side is the usual cause.</p></div><h3 id="double-click-to-open" tabindex="-1">Double-click to open <a class="header-anchor" href="#double-click-to-open" aria-label="Permalink to &quot;Double-click to open&quot;">​</a></h3><p>Install the viewer in Chrome or Edge and it registers <code>.ozx</code>, so double-clicking one in Finder or Explorer opens it straight in the viewer. No browser window to find first, no dragging.</p><p>Only <code>.ozx</code> is registered, never <code>.zip</code>. A microscopy viewer claiming every archive on your machine would be presumptuous, and most zips you double-click are not datasets. Rename a <code>.zip</code> to <code>.ozx</code> if you want this for it.</p><p>If the viewer is already open, the file opens in that window and asks before it replaces whatever you were looking at.</p><p>To install: open the viewer in Chrome or Edge and use <strong>Install</strong> in the address bar. See <a href="./../install-and-offline.html">Installing and Offline</a> for what else that gives you.</p><h3 id="nothing-is-unpacked-and-nothing-is-copied" tabindex="-1">Nothing is unpacked, and nothing is copied <a class="header-anchor" href="#nothing-is-unpacked-and-nothing-is-copied" aria-label="Permalink to &quot;Nothing is unpacked, and nothing is copied&quot;">​</a></h3><p>Opening an archive does not read it. The viewer reads the ZIP index, then only the pieces it needs, seeking straight to them inside the file.</p><p>Opening the 96-well plate used for testing this, 10 MB with 205 entries, reads <strong>0.08 MB to open it, 0.10 MB to work out the whole plate layout, and 0.41 MB by the time the first field is on screen.</strong> That is 3.9% of the file. The rest is never touched until you navigate to it. A dataset far too large to fit in memory opens exactly as fast, because size was never the thing being read.</p><p>Your data stays on your disk. It is not uploaded, and it is not copied into the browser either.</p><h3 id="from-an-address" tabindex="-1">From an address <a class="header-anchor" href="#from-an-address" aria-label="Permalink to &quot;From an address&quot;">​</a></h3><p>A zipped dataset opens from its address too. Paste the address and click <strong>Load from URL</strong>. It opens in 2D and in 3D, like a folder.</p><p>The viewer reads the file&#39;s table of contents from its end, then only the parts it needs for the view. It does not download the whole file. The server must allow CORS and answer range requests. See <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a>.</p><p>A Dropbox file link works too, but Dropbox takes several seconds per read. See <a href="./remote-urls.html#dropbox-file-links">Dropbox file links</a>.</p><h2 id="public-data-to-try" tabindex="-1">Public Data to Try <a class="header-anchor" href="#public-data-to-try" aria-label="Permalink to &quot;Public Data to Try&quot;">​</a></h2><p>The <a href="https://idr.openmicroscopy.org" target="_blank" rel="noreferrer">Image Data Resource (IDR)</a> hosts thousands of public microscopy datasets in OME-Zarr. Browse the IDR, find a dataset, and copy its Zarr address to open it here.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0079A/idr0079_images.zarr</span></span>
<span class="line"><span>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0001A/2551.zarr</span></span></code></pre></div><p>Most public OME-Zarr servers, such as the IDR and the BioImage Archive, already allow CORS. Or click <strong>Open Example</strong> on the landing page for datasets known to work well.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./supported-formats.html">Supported Formats</a>: every format the viewer opens.</li><li><a href="./local-files.html">Local Files</a> and <a href="./remote-urls.html">Remote URLs</a>: the two ways in, for every format.</li></ul>`,41)])])}const m=a(r,[["render",i]]);export{g as __pageData,m as default};
